mapper.select:
select s.carriage_number as carriageNumber, count(*) as seatCount from t_seat s join t_train_station requested_start on requested_start.train_id = s.train_id and requested_start.departure = #{departure} and requested_start.del_flag = 0 join t_train_station requested_end on requested_end.train_id = s.train_id and requested_end.arrival = #{arrival} and requested_end.del_flag = 0 where s.train_id = #{trainId} and s.del_flag = 0 and s.carriage_number in
#{carriage}
group by s.carriage_number

select s.seat_type as seatType, count(*) as seatCount from t_seat s join t_train_station requested_start on requested_start.train_id = s.train_id and requested_start.departure = #{startStation} and requested_start.del_flag = 0 join t_train_station requested_end on requested_end.train_id = s.train_id and requested_end.arrival = #{endStation} and requested_end.del_flag = 0 where s.train_id = #{trainId} and s.del_flag = 0 and s.seat_type in
#{seatType}
and not exists ( select straight_join 1 from t_ticket t join t_train_station sold_start on sold_start.train_id = t.train_id and sold_start.departure = t.departure and sold_start.del_flag = 0 join t_train_station sold_end on sold_end.train_id = t.train_id and sold_end.arrival = t.arrival and sold_end.del_flag = 0 where t.train_id = s.train_id and t.carriage_number = s.carriage_number and t.seat_number = s.seat_number and t.ticket_status in (0, 1, 2) and t.del_flag = 0 and cast(sold_start.sequence as unsigned) <= cast(requested_end.sequence as unsigned) and cast(sold_end.sequence as unsigned) >= cast(requested_start.sequence as unsigned) ) group by s.seat_type having seatCount > 0
